-- ProcurePilot schema migration 13/10: GRN workflow binding and role permissions
-- Generated by scripts/db/compose-prisma-migrations.js — do not edit by hand; edit manifest + sources.

-- ----- source: sql/custom/013_grn_workflow_binding_and_roles.sql -----
-- GRN: role permissions + workflow binding (submit → approve → post)
-- After deploy: POST /api/permissions/refresh/all or have users sign in again.

BEGIN;

-- Mirror purchase_order role grants onto goods_receipt
INSERT INTO role_permissions (role_id, feature_id, permissions, data_scope, can_approve, can_export, can_bulk_action)
SELECT
  rp.role_id,
  gr.id,
  rp.permissions,
  rp.data_scope,
  rp.can_approve,
  rp.can_export,
  rp.can_bulk_action
FROM role_permissions rp
JOIN features po ON po.id = rp.feature_id AND po.name = 'purchase_order'
JOIN modules m ON m.id = po.module_id AND m.name = 'procurement'
JOIN features gr ON gr.module_id = m.id AND gr.name = 'goods_receipt' AND gr.is_active = true
ON CONFLICT (role_id, feature_id) DO UPDATE SET
  permissions = EXCLUDED.permissions,
  data_scope = EXCLUDED.data_scope,
  can_approve = EXCLUDED.can_approve,
  can_export = EXCLUDED.can_export,
  can_bulk_action = EXCLUDED.can_bulk_action,
  updated_at = NOW();

-- Prefer PO workflow; fall back to PR workflow
INSERT INTO workflow_bindings (feature_id, event, definition_id, definition_version, created_by)
SELECT
  gr.id,
  'onStatusChange',
  sub.definition_id,
  sub.definition_version,
  1
FROM features gr
JOIN modules m ON m.id = gr.module_id AND m.name = 'procurement'
CROSS JOIN LATERAL (
  SELECT wb.definition_id, wb.definition_version
  FROM workflow_bindings wb
  JOIN features src ON src.id = wb.feature_id AND src.name IN ('purchase_order', 'purchase_requisition')
  JOIN workflow_definitions wd ON wd.id = wb.definition_id
    AND wd.status = 'published' AND wd.deprecated = false
  WHERE wb.event = 'onStatusChange' AND src.module_id = gr.module_id
  ORDER BY CASE src.name WHEN 'purchase_order' THEN 1 ELSE 2 END
  LIMIT 1
) sub
WHERE gr.name = 'goods_receipt' AND gr.is_active = true
  AND NOT EXISTS (
    SELECT 1 FROM workflow_bindings x WHERE x.feature_id = gr.id AND x.event = 'onStatusChange'
  )
ON CONFLICT (feature_id, event) DO UPDATE SET
  definition_id = EXCLUDED.definition_id,
  definition_version = EXCLUDED.definition_version;

-- Default L2 approval workflow when no PR/PO binding exists in the environment
DO $$
DECLARE
  gr_feature_id INTEGER;
  def_id INTEGER;
  def_version INTEGER;
  default_graph JSONB := '{"nodes":[
    {"id":"start","type":"start","label":"Start"},
    {"id":"approve_l2","type":"approval","label":"Department head approval","config":{"mode":"level","roleLevel":2,"departmentSource":"record.departmentId"}},
    {"id":"end_approved","type":"end","label":"Approved"},
    {"id":"end_rejected","type":"end","label":"Rejected"}
  ],"edges":[
    {"from":"start","to":"approve_l2"},
    {"from":"approve_l2","to":"end_approved","condition":"approved"},
    {"from":"approve_l2","to":"end_rejected","condition":"rejected"}
  ]}'::jsonb;
BEGIN
  SELECT f.id INTO gr_feature_id
  FROM features f
  JOIN modules m ON m.id = f.module_id
  WHERE m.name = 'procurement' AND f.name = 'goods_receipt' AND f.is_active = true
  LIMIT 1;

  IF gr_feature_id IS NULL THEN
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1 FROM workflow_bindings WHERE feature_id = gr_feature_id AND event = 'onStatusChange'
  ) THEN
    RETURN;
  END IF;

  SELECT id, version INTO def_id, def_version
  FROM workflow_definitions
  WHERE name = 'goods_receipt_approval' AND status = 'published'
  ORDER BY version DESC
  LIMIT 1;

  IF def_id IS NULL THEN
    INSERT INTO workflow_definitions (name, display_name, version, status, graph, created_by)
    VALUES ('goods_receipt_approval', 'Goods receipt approval', 1, 'published', default_graph, 1)
    RETURNING id, version INTO def_id, def_version;
  END IF;

  INSERT INTO workflow_bindings (feature_id, event, definition_id, definition_version, created_by)
  VALUES (gr_feature_id, 'onStatusChange', def_id, def_version, 1)
  ON CONFLICT (feature_id, event) DO UPDATE SET
    definition_id = EXCLUDED.definition_id,
    definition_version = EXCLUDED.definition_version;
END $$;

COMMIT;

